window.ATLAS.addDetails("society.edges",{"edges":{
"amortisation-schedule:equal-principal-vs-equal-payment":{"type":"foundation","label":{"zh":"欠得少、欠得短","en":"Owing less for less time"},"reason":{"zh":"第 4 章把第 3 章的还款表和等额本金对比：等额本金少付 11.7 万利息，只因为平均欠得少；利息之比恰好等于平均余额之比。","en":"Chapter 4 sets chapter 3’s schedule against equal-principal: equal-principal pays 117,000 less interest only because less is owed on average; the interest ratio equals the average-balance ratio exactly."},"source":"../economics/money/where-a-mortgage-payment-goes/#ch4"},
"amortisation-schedule:mortgage-prepayment":{"type":"foundation","label":{"zh":"提前还的钱不再计息","en":"Prepaid money stops bearing interest"},"reason":{"zh":"第 5 章在第 3 章的还款表上提前还 10 万：省下的利息取决于这笔钱原本还要欠多久，第 1 年还省 18.8 万，第 20 年只省 4.2 万。","en":"Chapter 5 prepays 100,000 on chapter 3’s schedule: the saving depends on how long the money would still have been owed, 188,000 in year 1 and 42,000 in year 20."},"source":"../economics/money/where-a-mortgage-payment-goes/#ch5"},
"annuity-payment-formula:amortisation-schedule":{"type":"foundation","label":{"zh":"把月供拆开","en":"Splitting the payment"},"reason":{"zh":"第 3 章把第 2 章的固定月供逐月拆成利息和本金：第一个月 3,333 元利息、1,441 元本金，第 153 个月本金才超过利息。","en":"Chapter 3 splits chapter 2’s level payment month by month: the first month is 3,333 interest and 1,441 principal, and principal overtakes interest only in month 153."},"source":"../economics/money/where-a-mortgage-payment-goes/#ch3"},
"auctions:game-theory":{"type":"application","label":{"zh":"占优策略的拍卖实例","en":"Dominant strategy in an auction"},"reason":{"zh":"第二价格拍卖里，无论对手怎么报，说真话都不比别的报价差，是占优策略的一个具体例子。","en":"In a second-price auction, telling the truth is never worse than any other bid whatever the rival does, a concrete dominant strategy."},"source":"../math/applied/auction-basics/#step1"},
"auctions:mechanism-auction":{"type":"foundation","label":{"zh":"拍卖是机制的一个实例","en":"An auction is one instance of a mechanism"},"reason":{"zh":"拍卖页讲出价与成交，机制页追问规则本身：同一群人、同一件物品，换一条成交规则，报价与结果全变。","en":"The auction page covers bids and sales; the mechanism page asks about the rule itself: same people, same item, a different settlement rule, and bids and outcome all change."},"source":"../math/applied/mechanism-design/#s1"},
"auctions:strategic-voting":{"type":"connection","label":{"zh":"说真话何时是占优策略","en":"When truth-telling is dominant"},"reason":{"zh":"第 5 章拿第二价格拍卖对照：拍卖里说真话是占优策略，而按吉巴德–萨特斯韦特定理，三个以上候选人时几乎每种投票规则都有说假话更好的时候。","en":"Chapter 5 contrasts the second-price auction, where truthful bidding is dominant, with voting: by the Gibbard–Satterthwaite theorem almost every rule with three or more candidates sometimes rewards misreporting."},"source":"../society/civics/same-votes-different-winner/#ch5"},
"binomial-normal:condorcet-jury-theorem":{"type":"foundation","label":{"zh":"多数判对的概率是二项尾概率","en":"The majority’s accuracy is a binomial tail"},"reason":{"zh":"第 9 章的陪审团定理用二项分布的尾概率：每人对的概率 0.6 时，11 人多数判对 75%，101 人 98%。","en":"Chapter 9’s jury theorem is a binomial tail probability: with each voter right 60% of the time, a majority of 11 is right 75% of the time and of 101, 98%."},"source":"../society/civics/same-votes-different-winner/#ch9"},
"compound-interest:fees-compounding":{"type":"foundation","label":{"zh":"费率改的是复利公式里的 r","en":"A fee changes the r in the compound formula"},"reason":{"zh":"复利 A = P(1+r)ᵗ；收 f 的费就变成 P(1+r−f)ᵗ。两条指数曲线的差距不是每年固定一点，而是随 t 越拉越大。","en":"Compounding gives A = P(1+r)ᵗ; a fee f turns it into P(1+r−f)ᵗ. The gap between the two exponential curves is not a fixed amount per year but widens with t."},"source":"../investment/rates/fees-compounding/#step1"},
"compound-interest:interest-price-of-time":{"type":"foundation","label":{"zh":"现值","en":"Present value"},"reason":{"zh":"第 6 章没有自己的模型，把现值交给复利与贴现的第 3 步：利率 4% 时一年后的 104 等于今天的 100，十年后的 100 只值 67.6。","en":"Chapter 6 has no model of its own and leaves present value to step 3 of Compound Interest & Discounting: at 4% 104 in a year equals 100 today, and 100 in ten years is worth 67.6."},"source":"../economics/money/where-money-comes-from/#ch6"},
"compound-interest:interest-rates-bonds":{"type":"foundation","label":{"zh":"折现是复利倒过来","en":"Discounting is compounding in reverse"},"reason":{"zh":"现值 PV = FV/(1+r)ᵗ 把复利公式倒过来；把债券的每笔未来现金逐一折现再加总，就是它今天的价格。","en":"Present value PV = FV/(1+r)ᵗ runs the compound-interest formula backwards; discount each of a bond’s future payments this way, add them up, and you have its price today."},"source":"../investment/rates/interest-rates-bonds/#step1"},
"compound-interest:loan-amortisation":{"type":"foundation","label":{"zh":"剩余本金","en":"The remaining principal"},"reason":{"zh":"第 7 章接着复利与贴现的第 5 步（剩余本金），补上那一页没有的：每年利息与本金的拆分、提前多还和固定月供的实际价值。","en":"Chapter 7 continues step 5 of Compound Interest & Discounting (remaining principal) and adds what that page lacks: the yearly interest/principal split, extra payments and the real value of a fixed payment."},"source":"../economics/money/where-money-comes-from/#ch7"},
"compound-interest:nominal-vs-effective-rate":{"type":"foundation","label":{"zh":"复利","en":"Compounding"},"reason":{"zh":"第 1 章：一年不还，第一个月的利息加进欠款，第二个月连它一起计息，这就是复利（“复利与贴现”第 1 步）；本章只看它给同一个利率起的三个名字。","en":"Chapter 1: with no payments, the first month’s interest joins the debt and earns interest the next month, which is compounding (step 1 of Compound Interest & Discounting); the chapter looks at the three names it gives one rate."},"source":"../economics/money/where-a-mortgage-payment-goes/#ch1"},
"condorcet-paradox:arrow-impossibility":{"type":"connection","label":{"zh":"让步的是不绕圈的排名","en":"A non-cyclic ranking gives way"},"reason":{"zh":"第 6 章回指第 4 章：多数排序可以绕成圈，两两对决就给不出完整不绕圈的排名。","en":"Chapter 6 points back to chapter 4: majority rankings can cycle, so pairwise contests cannot always give a complete ranking without cycles."},"source":"../society/civics/same-votes-different-winner/#ch6"},
"diversification:risk-pooling":{"type":"connection","label":{"zh":"同样的 1/√N 直觉，机制不同","en":"The same 1/√N intuition, a different mechanism"},"reason":{"zh":"保险靠很多人各自独立出险，平均下来就稳；投资分散靠资产低相关。两者都是“平均能熨平波动”，但共同灾难和系统风险都会让波动停在一个下限。","en":"Insurance relies on many people’s claims being independent, so the average is steady; diversification relies on low correlation between assets. Both are “averaging smooths the wobble”, and in both a common catastrophe or systematic risk leaves a floor."},"source":"../investment/basics/diversification/#step3"},
"ethical-frameworks:veil-of-ignorance":{"type":"connection","label":{"zh":"公平框架的一个思想实验","en":"A thought experiment for the fairness lens"},"reason":{"zh":"无知之幕让选择规则的人不知道自己会落在哪个位置，从而逼着他像关心自己一样关心最差的位置，是检验“代价是否公平分摊”的一个工具。","en":"The veil of ignorance hides from rule-makers which position they will occupy, forcing them to care about the worst position as if it were their own — a tool for testing whether costs are shared fairly."},"source":"../psychology/ethics/veil-of-ignorance/#step0"},
"exp-log:vowel-formants":{"type":"application","label":{"zh":"对数刻度让缩放变成平移","en":"A log scale turns rescaling into shifting"},"reason":{"zh":"元音图两轴用对数刻度，相同距离代表相同倍数；所以按说话人整体乘一个比例来归一化，在图上就是把整圈平移。","en":"Both axes of the vowel plot are logarithmic, so equal distances mean equal ratios; normalising a speaker by multiplying by one factor is then just shifting the whole loop."},"source":"../language/phonology/vowel-space/#step4"},
"expected-value:ethical-frameworks":{"type":"application","label":{"zh":"把后果写成期望值","en":"Writing consequences as an expected value"},"reason":{"zh":"结果主义的计算常写成 E = p·benefit − (1−p)·harm；它能比较后果，却不会自动回答同意、尊严或分配的问题。","en":"Consequentialist reckoning is often written E = p·benefit − (1−p)·harm; it compares outcomes, but does not by itself settle consent, dignity or distribution."},"source":"../psychology/ethics/ethics-decisions/#step1"},
"expected-value:risk-return":{"type":"foundation","label":{"zh":"期望不等于到手","en":"Expected is not received"},"reason":{"zh":"平均回报是所有可能结果按概率加权的期望值，到手的却是某一年真实发生的那一个；所以平均 5% 的投资里照样会冒出亏损的年份。","en":"The average return is the expected value — every possible outcome weighted by its probability — but what you actually get is the one outcome that happens in a given year; so an investment averaging 5% still throws up losing years."},"source":"../investment/basics/risk-return/#step4"},
"expected-value:veil-of-ignorance":{"type":"foundation","label":{"zh":"平均原则就是期望值","en":"The average rule is an expected value"},"reason":{"zh":"海萨尼假设落到每个位置的概率相等，于是比较各社会的平均福祉——正是对位置取期望值；罗尔斯的反驳则是：一生只抽一次，期望值未必是该看的数。","en":"Harsanyi assumes every position is equally likely and so compares average welfare — the expected value over positions; Rawls replies that with only one draw in a lifetime, the expected value is not necessarily the number to look at."},"source":"../psychology/ethics/veil-of-ignorance/#step1"},
"game-theory:externalities":{"type":"connection","label":{"zh":"公地悲剧是多人博弈","en":"The commons is a many-player game"},"reason":{"zh":"每个牧民各自最优的选择合起来使总利润下降，这是纳什均衡劣于合作结果的又一例。","en":"Each herder’s individually best choice adds up to lower total profit, another case of a Nash equilibrium worse than the cooperative outcome."},"source":"../math/applied/externalities/#step4"},
"game-theory:median-voter":{"type":"application","label":{"zh":"候选人位置的均衡","en":"Candidates’ positions in equilibrium"},"reason":{"zh":"第 3 章把霍特林的海滩冰淇淋摊交给博弈论的纳什均衡：两位候选人都站到中位选民的位置，谁也不愿单独挪开。","en":"Chapter 3 leaves Hotelling’s beach ice-cream stands to the Nash equilibrium of Game Theory: both candidates stand at the median voter and neither gains by moving alone."},"source":"../society/civics/same-votes-different-winner/#ch3"},
"inflation-winners-losers:inflation-opportunity-cost-loan":{"type":"foundation","label":{"zh":"通胀减轻固定还款","en":"Inflation lightens fixed payments"},"reason":{"zh":"“钱是从哪里来的”第 5 章说，物价上涨时固定利率借款人的实际负担变轻；第 8 章把它算出来：通胀 2% 时最后一期 4,774 元只值今天的 2,636 元。","en":"Chapter 5 of Where Money Comes From explained that rising prices lighten a fixed-rate borrower’s real burden; chapter 8 works it out: at 2% inflation the last 4,774 payment is worth 2,636 today."},"source":"../economics/money/where-a-mortgage-payment-goes/#ch8"},
"inflation-winners-losers:interest-price-of-time":{"type":"foundation","label":{"zh":"费雪关系用第 5 章的 4.04%","en":"The Fisher relation with chapter 5’s 4.04%"},"reason":{"zh":"第 6 章用第 5 章合同里的利率 4.04%（实际利率 2%、预期通胀 2%）讲费雪关系：名义利率 ≈ 实际利率 + 预期通胀。","en":"Chapter 6 uses the 4.04% rate of chapter 5’s contract (2% real, 2% expected inflation) for the Fisher relation: the nominal rate is about the real rate plus expected inflation."},"source":"../economics/money/where-money-comes-from/#ch6"},
"inflation-winners-losers:loan-amortisation":{"type":"connection","label":{"zh":"固定月供被通胀稀释","en":"Inflation thins a fixed payment"},"reason":{"zh":"第 7 章可以导入第 5 章的预期通胀，看固定月供的实际价值：通胀 2% 时，30 年后最后一期 4774 元只值今天的 2640 元。","en":"Chapter 7 can import chapter 5’s expected inflation to show a fixed payment’s real value: at 2% inflation the last of the 4,774 monthly payments is worth 2,640 in today’s money."},"source":"../economics/money/where-money-comes-from/#ch7"},
"interest-price-of-time:monetary-transmission":{"type":"foundation","label":{"zh":"利率升，旧债价跌","en":"Rates up, old bonds down"},"reason":{"zh":"第 8 章的传导链经过第 6 章：市场利率随政策利率变动，旧债券价格反向变化，新贷款利率在约 3 个月内跟上。","en":"Chapter 8’s chain passes through chapter 6: market rates follow the policy rate, old bond prices move the other way, and new-loan rates follow within about 3 months."},"source":"../economics/money/where-money-comes-from/#ch8"},
"interest-rates-bonds:interest-price-of-time":{"type":"foundation","label":{"zh":"为什么旧债券会跌","en":"Why old bonds fall"},"reason":{"zh":"第 6 章引用利率与债券的第 3 步：利率升了，折现变重，固定票息的旧债券必须降价才卖得掉。","en":"Chapter 6 cites step 3 of Interest Rates & Bonds: when rates rise discounting gets heavier, so an old fixed-coupon bond must fall in price to sell."},"source":"../economics/money/where-money-comes-from/#ch6"},
"loan-amortisation:amortisation-schedule":{"type":"connection","label":{"zh":"同一笔贷款","en":"The same loan"},"reason":{"zh":"“钱是从哪里来的”第 7 章用同一笔贷款展示了每年的利息和本金；第 3 章细看本金超过利息的转折点为什么落在那里。","en":"Chapter 7 of Where Money Comes From used the same loan to show each year’s interest and principal; chapter 3 looks closely at where the turning point falls and why."},"source":"../economics/money/where-a-mortgage-payment-goes/#ch3"},
"loans-create-deposits:monetary-transmission":{"type":"foundation","label":{"zh":"政策利率先是准备金的价格","en":"The policy rate prices reserves first"},"reason":{"zh":"第 8 章把传导链倒回第 2 章：央行设定的是银行之间借准备金的价格，贷款利率随后跟着变。","en":"Chapter 8 walks the chain back to chapter 2: the central bank sets the price at which banks borrow reserves, and loan rates follow."},"source":"../economics/money/where-money-comes-from/#ch8"},
"mechanism-auction:game-theory":{"type":"foundation","label":{"zh":"报价行为要用博弈来读","en":"Bidding behavior reads as a game"},"reason":{"zh":"每个竞标者都按私人价值算计着报，机制设计就是给这场算计定规则——报价不是随手写的数，是博弈里的策略。","en":"Every bidder calculates from private value, so mechanism design is rule-setting for that calculation — a bid is not a number written casually, it is a strategy in a game."},"source":"../math/applied/mechanism-design/#s0"},
"mechanism-auction:prisoners-dilemma":{"type":"connection","label":{"zh":"第二价让说真话不再吃亏","en":"Second-price makes truth-telling cost nothing"},"reason":{"zh":"第一价里人人压价藏真实价值，像囚徒困境里各自算计；第二价收第二高报价，说真话不再吃亏，规则改写了博弈的 payoff。","en":"Under first-price everyone shades their true value, calculating like prisoners in a dilemma; second-price charges the runner-up bid, so truth-telling stops costing anything — the rule rewrites the game's payoff."},"source":"../math/applied/mechanism-design/#s1"},
"median-voter:arrow-impossibility":{"type":"connection","label":{"zh":"让步的是不限制偏好","en":"Unrestricted preferences give way"},"reason":{"zh":"第 6 章回指第 3 章：中位选民定理靠单峰偏好成立，也就是放弃了“不限制偏好”这一条。","en":"Chapter 6 points back to chapter 3: the median voter theorem holds because preferences are single-peaked, which gives up the condition of unrestricted preferences."},"source":"../society/civics/same-votes-different-winner/#ch6"},
"monetary-transmission:floating-rate-reset":{"type":"connection","label":{"zh":"央行利率怎么传到房贷","en":"How the policy rate reaches mortgages"},"reason":{"zh":"第 6 章只看利率变了以后月供怎么变；央行利率怎么一步步传到房贷利率，见“钱是从哪里来的”第 8 章。","en":"Chapter 6 looks only at what a rate change does to the payment; how the central bank’s rate passes through to mortgage rates is chapter 8 of Where Money Comes From."},"source":"../economics/money/where-a-mortgage-payment-goes/#ch6"},
"montecarlo:auctions":{"type":"application","label":{"zh":"用随机抽样验证收益相等","en":"Simulation checks revenue equivalence"},"reason":{"zh":"多轮随机抽取估值并累计平均，两种规则的平均收益靠近同一个理论值，这是蒙特卡洛估计的直接应用。","en":"Drawing values at random over many rounds and averaging brings both rules to the same theoretical value, a direct use of Monte Carlo estimation."},"source":"../math/applied/auction-basics/#step2"},
"mortgage-prepayment:inflation-opportunity-cost-loan":{"type":"foundation","label":{"zh":"回答第 5 章留下的问题","en":"Answering chapter 5’s open question"},"reason":{"zh":"第 8 章回答第 5 章留下的问题：那 10 万不拿去还贷而拿去别处用会怎样；比较的标尺是贷款利率，收益率恰为 4% 时两者打平。","en":"Chapter 8 answers the question chapter 5 left open, what if the 100,000 went elsewhere instead of repaying the loan; the yardstick is the loan rate, and the two break even exactly at a 4% return."},"source":"../economics/money/where-a-mortgage-payment-goes/#ch8"},
"nominal-vs-effective-rate:annuity-payment-formula":{"type":"foundation","label":{"zh":"每月用 r/12","en":"Using r/12 each month"},"reason":{"zh":"第 2 章的月供按第 1 章的月利率 i = r/12 计算：余额每月乘 (1+i) 再减月供，4% 时只有 4,774.15 元恰好在第 360 个月还清。","en":"Chapter 2’s payment uses chapter 1’s monthly rate i = r/12: each month the balance is multiplied by (1+i) and the payment subtracted; at 4% only 4,774.15 clears it in month 360."},"source":"../economics/money/where-a-mortgage-payment-goes/#ch2"},
"phonemes:vowel-formants":{"type":"connection","label":{"zh":"辅音靠发音特征，元音靠共振峰","en":"Consonants by features, vowels by formants"},"reason":{"zh":"辅音的对立多由发音部位、方式和清浊这些开关决定；元音的区别则落在声道共鸣上，用前两个共振峰 F1、F2 在平面上定位。","en":"Consonant contrasts are mostly set by switches — place, manner and voicing; vowels differ in the vocal tract’s resonances and are located on a plane by the first two formants, F1 and F2."},"source":"../language/phonology/vowel-space/#step0"},
"prisoners-dilemma:game-theory":{"type":"connection","label":{"zh":"占优策略的反例式应用","en":"A dilemma built on dominance"},"reason":{"zh":"第 0 步的收益矩阵里背叛是占优策略，却使双方都不如合作，是博弈论“占优均衡不一定最优”的经典例子。","en":"In step 0’s payoff matrix defection is dominant yet leaves both worse than cooperating, the classic case that a dominant-strategy equilibrium need not be best."},"source":"../math/applied/prisoners-dilemma/#step0"},
"quantity-theory-inflation:inflation-winners-losers":{"type":"foundation","label":{"zh":"用第 4 章的长期通胀","en":"Using chapter 4’s long-run inflation"},"reason":{"zh":"第 5 章可以导入第 4 章机器里的长期通胀作为实际通胀，再看签约时预期的通胀和它差多少，差额决定财富从谁手里转到谁手里。","en":"Chapter 5 can import chapter 4’s long-run inflation as the actual rate and compare it with the inflation expected when the contract was signed; the gap decides who loses wealth to whom."},"source":"../economics/money/where-money-comes-from/#ch5"},
"quantity-theory-inflation:monetary-transmission":{"type":"connection","label":{"zh":"价格是黏的","en":"Prices are sticky"},"reason":{"zh":"第 8 章用第 4 章的黏性价格解释为什么利率要一到三年才传到物价：默认设定下支出在第 19 个月、通胀在第 25 个月到谷底。","en":"Chapter 8 uses chapter 4’s sticky prices to explain why a rate change takes one to three years to reach prices: by default spending bottoms in month 19 and inflation in month 25."},"source":"../economics/money/where-money-comes-from/#ch8"},
"quantity-theory-inflation:purchasing-power-parity":{"type":"foundation","label":{"zh":"本国通胀推动平价","en":"Home inflation moves parity"},"reason":{"zh":"第 9 章可以导入第 4 章的长期通胀作为本国通胀；购买力平价随两国通胀之比移动，默认本国通胀 5% 时 20 年后从 5 变成 8.93。","en":"Chapter 9 can import chapter 4’s long-run inflation as home inflation; purchasing-power parity moves with the ratio of the two countries’ inflation, from 5 to 8.93 after 20 years at the default 5% home inflation."},"source":"../economics/money/where-money-comes-from/#ch9"},
"regression-correlation:diversification":{"type":"foundation","label":{"zh":"ρ 从 1 到 −1","en":"ρ from 1 to −1"},"reason":{"zh":"等权两只资产时组合波动是 σ·√((1+ρ)/2)：ρ = 1 不降，ρ = 0 降到约 0.71 倍，ρ = −1 完全抵消——相关系数就是“是否一起动”的那个数。","en":"With two equal-weight assets the portfolio volatility is σ·√((1+ρ)/2): no reduction at ρ = 1, down to about 0.71 times at ρ = 0, fully cancelled at ρ = −1 — the correlation coefficient is the number for “moving together”."},"source":"../investment/basics/diversification/#step1"},
"resonance:vowel-formants":{"type":"foundation","label":{"zh":"声道是一组共鸣腔","en":"The vocal tract is a set of resonators"},"reason":{"zh":"从喉到唇的声道像共鸣腔，把某些频率附近的谐波放大；舌头和嘴唇改变腔的形状，共振频率跟着移动，元音就变了。","en":"The tract from larynx to lips acts like a resonator, amplifying harmonics near certain frequencies; tongue and lips change its shape, the resonant frequencies move, and the vowel changes."},"source":"../language/phonology/vowel-space/#step0"},
"sound-vibration:phonemes":{"type":"foundation","label":{"zh":"浊音就是声带在振动","en":"Voicing is the vocal folds vibrating"},"reason":{"zh":"声音来自振动；清和浊的区别不是音量，而是发音时声带振不振动——摸着喉咙念 /s/ 和 /z/ 就能感觉到。","en":"Sound comes from vibration; voiceless versus voiced is not about loudness but whether the vocal folds vibrate — touch your throat while saying /s/ and /z/ and you can feel it."},"source":"../language/phonology/phonemes/#step0"},
"spectrum:vowel-formants":{"type":"foundation","label":{"zh":"元音的频谱：谐波加包络峰","en":"A vowel’s spectrum: harmonics under envelope peaks"},"reason":{"zh":"浊音的波形每秒重复 F0 次，频谱上是 F0、2F0、3F0…… 一排谐波；共振峰是这些谐波上方包络的峰，要在频谱里才看得见。","en":"A voiced sound repeats F0 times a second, giving a row of harmonics at F0, 2F0, 3F0 … in its spectrum; formants are peaks in the envelope over those harmonics, visible only in the spectrum."},"source":"../language/phonology/vowel-space/#step0"},
"spoiler-effect:arrow-impossibility":{"type":"connection","label":{"zh":"让步的是无关选项独立","en":"Independence of irrelevant alternatives gives way"},"reason":{"zh":"第 6 章回指第 2 章：搅局者改变赢家，就是“无关选项独立”这一条在让步。","en":"Chapter 6 points back to chapter 2: a spoiler changing the winner is the condition of independence of irrelevant alternatives giving way."},"source":"../society/civics/same-votes-different-winner/#ch6"},
"spoiler-effect:duverger-tendency":{"type":"foundation","label":{"zh":"被预期到的搅局者","en":"The spoiler, anticipated"},"reason":{"zh":"第 2 章第二个模型：选民预期第三名会搅局，便逐届改投第二选择；默认 s = 0.35 时第 10 届起第三名不到 0.5%。","en":"Chapter 2’s second model: voters who expect the third candidate to spoil switch to their second choice election by election; at the default s = 0.35 the third candidate is below 0.5% from election 10."},"source":"../society/civics/same-votes-different-winner/#ch2"},
"spoiler-effect:median-voter":{"type":"foundation","label":{"zh":"一维用第 2 章的选民","en":"The 1-D case uses chapter 2’s voters"},"reason":{"zh":"第 3 章一维的胜集用第 2 章的选民：从 0.15 出发的挑战者一届届收敛到中位 0.48 后停下。","en":"Chapter 3’s one-dimensional win set uses chapter 2’s voters: challengers starting from 0.15 converge to the median 0.48 and stop."},"source":"../society/civics/same-votes-different-winner/#ch3"},
"stocks-bonds:interest-rates-bonds":{"type":"foundation","label":{"zh":"债券是一串约定的未来现金","en":"A bond is a promised stream of future cash"},"reason":{"zh":"先知道债券每年付票息、到期还本，才能把它看成一串未来现金流，再按利率折现成今天的价格。","en":"Knowing that a bond pays a coupon every year and returns its principal at maturity is what lets it be seen as a stream of future cash, which interest rates then discount into today’s price."},"source":"../investment/rates/interest-rates-bonds/#step0"},
"stocks-bonds:risk-return":{"type":"connection","label":{"zh":"清偿顺序决定风险","en":"Repayment order sets the risk"},"reason":{"zh":"债主先拿、股东最后拿，所以股票的结果散得更开：好时分红和涨价没有上限，坏时可能归零——风险更大，平均回报也必须更高。","en":"Lenders are paid first and shareholders last, so a stock’s outcomes are spread wider: no cap on dividends and gains in good times, possibly zero in bad — more risk, which must be paid for with a higher average return."},"source":"../investment/basics/stocks-bonds/#step3"},
"supply-demand:externalities":{"type":"application","label":{"zh":"价格漏掉了一部分成本","en":"The price leaves out part of the cost"},"reason":{"zh":"供需均衡只反映买卖双方的私人成本与好处；加上外部损害后社会成本线高于供给线，均衡就偏离社会最优。","en":"Supply–demand equilibrium reflects only the buyers’ and sellers’ private costs and benefits; adding external damage lifts the social cost line above supply and moves equilibrium away from the social optimum."},"source":"../math/applied/externalities/#step1"},
"supply-demand:game-theory":{"type":"connection","label":{"zh":"均衡之外还要看策略互动","en":"Beyond equilibrium, watch strategic interaction"},"reason":{"zh":"供需均衡算的是价格把买卖双方撮合到哪；一旦一方的行动影响另一方的收益（公地、污染），就要用博弈论算每个人在对手行动下的最佳回应——外部性问题正是均衡分析走到博弈论的路口。","en":"Supply-demand equilibrium computes where price matches buyers and sellers; once one side's action affects another's payoff (commons, pollution), game theory computes each player's best response to rivals' moves — externality problems are exactly where equilibrium analysis meets game theory."},"source":"../math/applied/externalities/#step4"},
"supply-demand:stocks-bonds":{"type":"application","label":{"zh":"价格由买卖双方定","en":"Buyers and sellers set the price"},"reason":{"zh":"没人给股票贴价签：想买的人多、想卖的人少，成交价就被抬高，反过来就压低——这就是供求决定价格的机制。","en":"Nobody puts a price tag on a share: more eager buyers than sellers push the trading price up, and the reverse pushes it down — supply and demand at work."},"source":"../investment/basics/stocks-bonds/#step4"},
"variance:diversification":{"type":"foundation","label":{"zh":"组合的方差公式","en":"The portfolio variance formula"},"reason":{"zh":"两只资产组合的波动 σₚ = √(w₁²σ₁² + w₂²σ₂² + 2w₁w₂ρσ₁σ₂)：交叉项里有相关系数 ρ，正是它决定组合能抵消掉多少波动。","en":"A two-asset portfolio’s volatility is σₚ = √(w₁²σ₁² + w₂²σ₂² + 2w₁w₂ρσ₁σ₂): the cross term carries the correlation ρ, which decides how much wobble the mix cancels."},"source":"../investment/basics/diversification/#step1"},
"variance:risk-return":{"type":"foundation","label":{"zh":"用方差量风险","en":"Variance measures risk"},"reason":{"zh":"两种投资平均都是 5%，一个挤在 5% 附近，一个铺到 −10% 到 +20%；方差量的就是结果离平均有多散——散开意味着可能更好，也可能更糟。","en":"Two investments both average 5%, one clustered near 5% and one spread from −10% to +20%; variance measures how scattered the results are around the average — scattered means possibly better, and possibly worse."},"source":"../investment/basics/risk-return/#step1"},
"veil-of-ignorance:reading-fairness-claims":{"type":"connection","label":{"zh":"不知道自己是谁时选规则","en":"Choosing rules before knowing who you are"},"reason":{"zh":"第 10 章给出读“公平”的五个问题，其中一个把读者引到无知之幕：如果事先不知道自己会站在哪一边，你会选哪种规则。","en":"Chapter 10 gives five questions for reading “fair”; one sends the reader to the veil of ignorance: which rule would you choose before knowing which side you will be on?"},"source":"../society/civics/same-votes-different-winner/#ch10"},
"voting-rules-disagree:arrow-impossibility":{"type":"connection","label":{"zh":"认可投票的门槛","en":"The approval threshold"},"reason":{"zh":"第 6 章的认可投票复用第 1 章的选民：认可半径 r ≤ 0.19 时与得票最多相同（B 赢），r ≥ 0.20 时 C 赢，门槛本身改变结果。","en":"Chapter 6’s approval voting reuses chapter 1’s voters: with approval radius r ≤ 0.19 it agrees with plurality (B wins), from r = 0.20 C wins; the threshold itself changes the result."},"source":"../society/civics/same-votes-different-winner/#ch6"},
"voting-rules-disagree:strategic-voting":{"type":"foundation","label":{"zh":"同一批选民，找一组说假话得利的人","en":"Same voters: find a group that gains by misreporting"},"reason":{"zh":"第 5 章在第 1 章的选民和候选人上搜索：得票最多规则下，C>D>A>B 的 13 人中 9 人改票就能让赢家从 B 变成 A。","en":"Chapter 5 searches chapter 1’s voters and candidates: under plurality, 9 of the 13 voters ranking C>D>A>B can switch the winner from B to A by misreporting."},"source":"../society/civics/same-votes-different-winner/#ch5"}
}});
